var ENT=[["Kernel", "Signature Kernel pillar of the Linker framework."], ["Evaluator", "Signature Evaluator pillar of the Linker framework."], ["Collector", "Signature Collector pillar of the Linker framework."], ["Scheduler", "Signature Scheduler pillar of the Linker framework."], ["Sandbox", "Signature Sandbox pillar of the Linker framework."], ["Bridge", "Signature Bridge pillar of the Linker framework."], ["Console", "Signature Console pillar of the Linker framework."]];
var TECH=[["Bytecode interpretation", "A compact instruction set executed by a portable virtual machine loop."], ["Just-in-time compilation", "Compiling hot code paths to native machine code at runtime for speed."], ["Garbage collection", "Automatic memory reclamation via tracing mark-sweep or reference counting."], ["Event-loop concurrency", "Single-threaded async I/O multiplexing instead of one-thread-per-connection."], ["Ahead-of-time compilation", "Compiling to native binaries before execution for fast startup."], ["Foreign function interfaces", "Calling C and native libraries from managed languages across an ABI boundary."], ["Sandboxed execution", "Running untrusted code with restricted capabilities, e.g. WASM linear memory or Deno permissions."], ["REPL-driven development", "Read-eval-print loops for interactive language experimentation."], ["Type checking", "Static verification of type correctness before or during execution."], ["Module systems", "Namespaced code units with explicit dependency declarations."]];
